package cl.acis.ordenes.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="ordenes_trabajo",uniqueConstraints=@UniqueConstraint(name="uk_orden_codigo",columnNames="codigo")) public class OrdenTrabajo {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String codigo; @Column(nullable=false) Long clienteId; Long equipoId; @Column(nullable=false) String tipoServicio; @Enumerated(EnumType.STRING) @Column(nullable=false) Prioridad prioridad; @Enumerated(EnumType.STRING) @Column(nullable=false) EstadoOrden estado=EstadoOrden.CREADA; Long tecnicoId; @Column(nullable=false) Long creadoPorId; LocalDateTime fechaProgramada; @Column(nullable=false,length=2000) String descripcion; String comentarioCliente; int slaHoras; LocalDateTime checkInEn; Double checkInLat,checkInLon; LocalDateTime checkOutEn; Double checkOutLat,checkOutLon; String diagnostico,actividades,materiales; @Column(nullable=false) LocalDateTime creadoEn; @Column(nullable=false) LocalDateTime modificadoEn;
 public OrdenTrabajo(){} @PrePersist void crear(){creadoEn=LocalDateTime.now();modificadoEn=creadoEn;} @PreUpdate void actualizar(){modificadoEn=LocalDateTime.now();}
 public Long getId(){return id;} public String getCodigo(){return codigo;} public void setCodigo(String v){codigo=v;} public Long getClienteId(){return clienteId;} public void setClienteId(Long v){clienteId=v;} public Long getEquipoId(){return equipoId;} public void setEquipoId(Long v){equipoId=v;} public String getTipoServicio(){return tipoServicio;} public void setTipoServicio(String v){tipoServicio=v;} public Prioridad getPrioridad(){return prioridad;} public void setPrioridad(Prioridad v){prioridad=v;} public EstadoOrden getEstado(){return estado;} public void setEstado(EstadoOrden v){estado=v;} public Long getTecnicoId(){return tecnicoId;} public void setTecnicoId(Long v){tecnicoId=v;} public Long getCreadoPorId(){return creadoPorId;} public void setCreadoPorId(Long v){creadoPorId=v;} public LocalDateTime getFechaProgramada(){return fechaProgramada;} public void setFechaProgramada(LocalDateTime v){fechaProgramada=v;} public String getDescripcion(){return descripcion;} public void setDescripcion(String v){descripcion=v;} public String getComentarioCliente(){return comentarioCliente;} public void setComentarioCliente(String v){comentarioCliente=v;} public int getSlaHoras(){return slaHoras;} public void setSlaHoras(int v){slaHoras=v;} public LocalDateTime getCheckInEn(){return checkInEn;} public void setCheckInEn(LocalDateTime v){checkInEn=v;} public Double getCheckInLat(){return checkInLat;} public void setCheckInLat(Double v){checkInLat=v;} public Double getCheckInLon(){return checkInLon;} public void setCheckInLon(Double v){checkInLon=v;} public LocalDateTime getCheckOutEn(){return checkOutEn;} public void setCheckOutEn(LocalDateTime v){checkOutEn=v;} public Double getCheckOutLat(){return checkOutLat;} public void setCheckOutLat(Double v){checkOutLat=v;} public Double getCheckOutLon(){return checkOutLon;} public void setCheckOutLon(Double v){checkOutLon=v;} public String getDiagnostico(){return diagnostico;} public void setDiagnostico(String v){diagnostico=v;} public String getActividades(){return actividades;} public void setActividades(String v){actividades=v;} public String getMateriales(){return materiales;} public void setMateriales(String v){materiales=v;} public LocalDateTime getCreadoEn(){return creadoEn;} public LocalDateTime getModificadoEn(){return modificadoEn;}
}
